  `def_id` bigint(20) NULL DEFAULT NULL,
  `def_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '流程标识',
  `def_version` int(11) NULL DEFAULT NULL,
  `def_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '流程名称快照',
  `business_key` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '业务键',
  `title` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '流程标题',
  `form_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '表单数据快照（JSON）',
  `inst_status` int(11) NOT NULL DEFAULT 0 COMMENT '0运行中 1已完成 2已挂起 3被驳回 4已终止 5已取消',
  `priority` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'normal' COMMENT '优先级 low/normal/high/urgent',
  `due_time` datetime NULL DEFAULT NULL COMMENT '预计完成时间',
  `start_user` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发起人',
  `start_time` datetime NULL DEFAULT NULL COMMENT '发起时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `current_nodes` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '当前活动节点（逗号分隔）',
  `vars_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '流程变量（JSON）',
  `create_time` datetime NULL DEFAULT NULL,
  `create_user` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `update_user` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `status` int(11) NOT NULL DEFAULT 1 COMMENT '1有效 0删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_instance_id`(`instance_id` ASC) USING BTREE,
  INDEX `idx_def_key`(`def_key` ASC) USING BTREE,
  INDEX `idx_start_user`(`start_user` ASC) USING BTREE,
  INDEX `idx_inst_status`(`inst_status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '流程实例' ROW_FORMAT = Dynamic;

